#!/usr/bin/env bash
# topup-pierce.sh SEAT TARGET x,y [x,y ...] — at the current stop, top each listed gun turret's piercing up to TARGET (no walking; turrets holding yellow are skipped).
LIB="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
seat=$1; tgt=$2; shift 2
pts=""; for xy in "$@"; do pts="$pts{${xy}},"; done
"$LIB/act.sh" exec_lua "$seat" code="local S='$seat' local s=game.surfaces[1] local o={} for _,p in ipairs({$pts}) do local e=s.find_entities_filtered{name='gun-turret',position=p,radius=0.6}[1] if not e then o[#o+1]=string.format('(%d,%d)MISSING',p[1],p[2]) else local inv=e.get_inventory(defines.inventory.turret_ammo) if inv.get_item_count('firearm-magazine')>0 then o[#o+1]=string.format('(%d,%d)yellow%d',p[1],p[2],inv.get_item_count('firearm-magazine')) else local need=$tgt-inv.get_item_count('piercing-rounds-magazine') local have=player.get_main_inventory().get_item_count('piercing-rounds-magazine') if need>have then need=have end local err='' if need>0 then local ok=pcall(remote.call,'game_bot','insert',{seat=S,x=p[1],y=p[2],name='piercing-rounds-magazine',count=need,target='gun-turret'}) if not ok then err='FAIL' end end o[#o+1]=string.format('(%d,%d)p%d%s',p[1],p[2],inv.get_item_count('piercing-rounds-magazine'),err) end end end rcon.print(table.concat(o,' ')..' | left '..player.get_main_inventory().get_item_count('piercing-rounds-magazine'))" | jq -r '.output // .'
